package com.profittracker;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Comparator;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

class ProfitTrackerPanel extends PluginPanel
{
	private static final DateTimeFormatter REFRESH_FORMAT = DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());

	private final ProfitTrackerSession session;
	private final ItemManager itemManager;
	private final ProfitTrackerConfig config;
	private final Runnable resetCallback;
	private final Runnable pauseCallback;
	private final JPanel content = new JPanel();
	private final JButton pause = new JButton("Pause");

	ProfitTrackerPanel(
		ProfitTrackerSession session,
		ItemManager itemManager,
		ProfitTrackerConfig config,
		Runnable resetCallback,
		Runnable pauseCallback
	)
	{
		super(false);
		this.session = session;
		this.itemManager = itemManager;
		this.config = config;
		this.resetCallback = resetCallback;
		this.pauseCallback = pauseCallback;

		setLayout(new BorderLayout());
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel controls = new JPanel(new GridLayout(1, 2, 6, 0));
		controls.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JButton reset = new JButton("Reset");
		reset.addActionListener(event -> resetCallback.run());
		pause.addActionListener(event -> pauseCallback.run());
		controls.add(reset);
		controls.add(pause);

		add(controls, BorderLayout.NORTH);
		add(new JScrollPane(content), BorderLayout.CENTER);
	}

	void rebuild(Instant lastRefresh, boolean usingWikiPrices)
	{
		content.removeAll();
		pause.setText(session.isPaused() ? "Resume" : "Pause");
		pause.setEnabled(session.isStarted());

		content.add(section("Session",
			row("Status", session.getStatus()),
			row("Elapsed", formatDuration(session.getElapsed())),
			row("Kills", Integer.toString(session.getKillCount())),
			row("Loot", formatGp(session.getLootValue())),
			row("Supplies", formatGp(session.getSupplyCost())),
			row("Profit", formatGp(session.getProfit())),
			row("Profit/hr", formatGp(session.getProfitPerHour())),
			row("Prices", priceStatus(lastRefresh, usingWikiPrices))
		));

		if (session.getTargets().isEmpty())
		{
			content.add(message("Kill an NPC to start tracking this trip."));
		}

		if (config.showNotableDrops() && !session.getNotableDrops().isEmpty())
		{
			content.add(notableDropsSection());
		}

		for (ProfitTrackerTarget target : session.getTargets())
		{
			content.add(targetSection(target));
		}

		content.revalidate();
		content.repaint();
	}

	private JPanel targetSection(ProfitTrackerTarget target)
	{
		final JPanel targetPanel = section(target.getName(),
			row("Kills", Integer.toString(target.getKills())),
			row("Loot", formatGp(target.getLootValue())),
			row("Avg kill", formatGp(target.getAverageKillValue())),
			row("Profit share", formatGp(target.getProfitShare(session.getProfit(), session.getLootValue())))
		);

		if (config.showDropBreakdown() && !target.getDrops().isEmpty())
		{
			targetPanel.add(subtitle("Top drops"));
			target.getDrops().values().stream()
				.sorted(Comparator.comparingLong(ProfitTrackerDrop::getValue).reversed())
				.limit(config.maxDropsShown())
				.forEach(drop -> targetPanel.add(row(itemName(drop.getItemId()) + " x" + drop.getQuantity(), formatGp(drop.getValue()))));
		}

		return targetPanel;
	}

	private JPanel notableDropsSection()
	{
		final JPanel panel = section("Notable drops");
		session.getNotableDrops().stream()
			.limit(config.maxNotableDrops())
			.forEach(drop -> panel.add(notableDropRow(drop)));
		return panel;
	}

	private JPanel notableDropRow(ProfitTrackerNotableDrop drop)
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		final JLabel icon = new JLabel(new ImageIcon(itemManager.getImage(drop.getItemId(), drop.getQuantity(), false)));
		final JLabel text = new JLabel("<html>" + itemName(drop.getItemId()) + " x" + drop.getQuantity()
			+ "<br><span style='color:#aaaaaa'>" + drop.getNpcName() + " kc " + drop.getKillCount() + "</span></html>");
		final JLabel value = new JLabel(formatGp(drop.getValue()), SwingConstants.RIGHT);

		row.add(icon, BorderLayout.WEST);
		row.add(text, BorderLayout.CENTER);
		row.add(value, BorderLayout.EAST);
		return row;
	}

	private String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (Exception ex)
		{
			return "Item " + itemId;
		}
	}

	private static JPanel section(String title, JPanel... rows)
	{
		final JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		section.setBorder(BorderFactory.createTitledBorder(title));
		for (JPanel row : rows)
		{
			section.add(row);
		}
		section.setMaximumSize(new Dimension(Integer.MAX_VALUE, section.getPreferredSize().height));
		return section;
	}

	private static JPanel message(String text)
	{
		final JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 6, 8, 6));
		panel.add(new JLabel(text), BorderLayout.CENTER);
		return panel;
	}

	private static JPanel subtitle(String text)
	{
		final JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 6, 2, 6));
		panel.add(new JLabel(text), BorderLayout.WEST);
		return panel;
	}

	static JPanel row(String label, String value)
	{
		final JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		final JLabel name = new JLabel(label);
		final JLabel amount = new JLabel(value, SwingConstants.RIGHT);
		row.add(name, BorderLayout.WEST);
		row.add(amount, BorderLayout.EAST);
		return row;
	}

	static String priceStatus(Instant lastRefresh, boolean usingWikiPrices)
	{
		if (lastRefresh == null)
		{
			return "loading";
		}
		return (usingWikiPrices ? "live " : "fallback ") + REFRESH_FORMAT.format(lastRefresh);
	}

	static String formatDuration(Duration duration)
	{
		final long seconds = duration.getSeconds();
		final long hours = seconds / 3600;
		final long minutes = seconds % 3600 / 60;
		final long rest = seconds % 60;
		return String.format("%02d:%02d:%02d", hours, minutes, rest);
	}

	static String formatGp(long value)
	{
		final String sign = value < 0 ? "-" : "";
		final long absolute = Math.abs(value);
		if (absolute >= 1_000_000)
		{
			return sign + String.format("%.2fm", absolute / 1_000_000.0);
		}
		if (absolute >= 1_000)
		{
			return sign + String.format("%.1fk", absolute / 1_000.0);
		}
		return sign + absolute + " gp";
	}
}

package com.profittracker;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "NPC Profit Tracker",
	description = "Tracks NPC kill loot, supply cost, and profit per hour with live OSRS Wiki prices.",
	tags = {"boss", "loot", "npc", "profit", "supplies"}
)
public class ProfitTrackerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ProfitTrackerConfig config;

	private ProfitTrackerPriceService priceService;
	private ProfitTrackerPanel panel;
	private NavigationButton navButton;
	private final Map<Integer, Integer> lastCarriedItems = new HashMap<>();
	private final ProfitTrackerSession session = new ProfitTrackerSession();
	private final ProfitTrackerInventory inventory = new ProfitTrackerInventory();
	private long lastCarriedValue;
	private boolean hasCarriedSnapshot;
	private boolean carriedItemsDirty;
	private boolean pendingSupplyAction;
	private boolean pendingIgnoredInventoryAction;

	@Override
	protected void startUp()
	{
		priceService = new ProfitTrackerPriceService(itemManager, config);
		priceService.start();

		panel = new ProfitTrackerPanel(session, itemManager, config, this::resetSession, this::togglePaused);
		navButton = NavigationButton.builder()
			.tooltip("Profit Tracker")
			.icon(createIcon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		captureInventorySnapshot();
		refreshPanel();
		log.debug("Profit Tracker started");
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		priceService.stop();
		lastCarriedItems.clear();
		hasCarriedSnapshot = false;
		carriedItemsDirty = false;
		pendingSupplyAction = false;
		pendingIgnoredInventoryAction = false;
		session.reset();
		log.debug("Profit Tracker stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			captureInventorySnapshot();
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		final NPC npc = event.getNpc();
		final String npcName = npc == null || npc.getName() == null ? "Unknown NPC" : npc.getName();
		final boolean wasEmpty = session.getKillCount() == 0;

		session.recordKill(npcName, event.getItems(), priceService, config.notableDropThreshold());

		if (wasEmpty && config.announceNewSession())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Profit Tracker started for " + npcName + ".", null);
		}

		refreshPanel();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final String option = event.getMenuOption();
		if (isSupplyUseOption(option))
		{
			pendingSupplyAction = true;
		}
		else if (isIgnoredInventoryOption(option))
		{
			pendingIgnoredInventoryAction = true;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INVENTORY.getId() && event.getContainerId() != InventoryID.EQUIPMENT.getId())
		{
			return;
		}

		carriedItemsDirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!carriedItemsDirty)
		{
			return;
		}

		carriedItemsDirty = false;
		final Map<Integer, Integer> current = carriedItems();
		final long currentValue = inventoryValue(current);

		maybeRecordSupplyLoss(currentValue);

		pendingSupplyAction = false;
		pendingIgnoredInventoryAction = false;
		lastCarriedItems.clear();
		lastCarriedItems.putAll(current);
		lastCarriedValue = currentValue;
		hasCarriedSnapshot = true;
	}

	private void maybeRecordSupplyLoss(long currentValue)
	{
		if (!config.countSupplyLosses() || !hasCarriedSnapshot || !session.isStarted() || session.isPaused())
		{
			return;
		}

		final boolean countPassiveLoss = config.countPassiveResourceLosses() && !pendingIgnoredInventoryAction;
		if (!pendingSupplyAction && !countPassiveLoss)
		{
			return;
		}

		final long valueLost = lastCarriedValue - currentValue;
		if (valueLost > 0)
		{
			session.recordSupplyCost(valueLost);
			refreshPanel();
		}
	}

	void resetSession()
	{
		session.reset();
		captureInventorySnapshot();
		refreshPanel();
	}

	void togglePaused()
	{
		session.togglePaused();
		captureInventorySnapshot();
		refreshPanel();
	}

	private void captureInventorySnapshot()
	{
		final Map<Integer, Integer> carried = carriedItems();
		lastCarriedItems.clear();
		lastCarriedItems.putAll(carried);
		lastCarriedValue = inventoryValue(lastCarriedItems);
		hasCarriedSnapshot = true;
		carriedItemsDirty = false;
		pendingSupplyAction = false;
		pendingIgnoredInventoryAction = false;
	}

	private Map<Integer, Integer> carriedItems()
	{
		final Map<Integer, Integer> quantities = new HashMap<>();
		mergeContainer(quantities, client.getItemContainer(InventoryID.INVENTORY));
		mergeContainer(quantities, client.getItemContainer(InventoryID.EQUIPMENT));
		return quantities;
	}

	private Map<Integer, Integer> toQuantityMap(ItemContainer container)
	{
		final Map<Integer, Integer> quantities = new HashMap<>();
		mergeContainer(quantities, container);
		return quantities;
	}

	private void mergeContainer(Map<Integer, Integer> quantities, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}

		Arrays.stream(container.getItems())
			.filter(item -> item.getId() > 0 && item.getQuantity() > 0)
			.forEach(item ->
			{
				final int id = itemManager.canonicalize(item.getId());
				quantities.merge(id, item.getQuantity(), Integer::sum);
			});
	}

	private long inventoryValue(Map<Integer, Integer> quantities)
	{
		return inventory.value(quantities, priceService);
	}

	static boolean isSupplyUseOption(String option)
	{
		if (option == null)
		{
			return false;
		}

		final String normalized = option.toLowerCase();
		return normalized.equals("eat")
			|| normalized.equals("drink")
			|| normalized.equals("consume")
			|| normalized.equals("guzzle")
			|| normalized.equals("sip");
	}

	static boolean isIgnoredInventoryOption(String option)
	{
		if (option == null)
		{
			return false;
		}

		final String normalized = option.toLowerCase();
		return normalized.equals("drop")
			|| normalized.equals("deposit")
			|| normalized.equals("deposit-all")
			|| normalized.equals("deposit-all-but-one")
			|| normalized.equals("bank")
			|| normalized.equals("store")
			|| normalized.equals("offer")
			|| normalized.equals("sell")
			|| normalized.equals("wield")
			|| normalized.equals("wear")
			|| normalized.equals("remove")
			|| normalized.equals("take")
			|| normalized.equals("withdraw");
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		SwingUtilities.invokeLater(() -> panel.rebuild(priceService.getLastRefresh(), priceService.isUsingWikiPrices()));
	}

	private static BufferedImage createIcon()
	{
		final BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(42, 136, 86));
		graphics.fillRoundRect(1, 1, 14, 14, 4, 4);
		graphics.setColor(new Color(245, 211, 93));
		graphics.fillOval(4, 3, 8, 8);
		graphics.setColor(new Color(32, 32, 32));
		graphics.drawString("g", 5, 13);
		graphics.dispose();
		return image;
	}

	@Provides
	ProfitTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ProfitTrackerConfig.class);
	}
}

package com.profittracker;

interface ProfitTrackerPriceLookup
{
	int getLivePrice(int itemId);
}

package com.profittracker;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;

@Slf4j
class ProfitTrackerPriceService implements ProfitTrackerPriceLookup
{
	private static final String LATEST_PRICES_URL = "https://prices.runescape.wiki/api/v1/osrs/latest";
	private static final String USER_AGENT = "RuneLite Profit Tracker plugin - local development";

	private final ItemManager itemManager;
	private final ProfitTrackerConfig config;
	private final Map<Integer, Integer> wikiPrices = new ConcurrentHashMap<>();
	private ScheduledExecutorService executor;

	@Getter
	private Instant lastRefresh;

	@Getter
	private boolean usingWikiPrices;

	ProfitTrackerPriceService(ItemManager itemManager, ProfitTrackerConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
	}

	void start()
	{
		executor = Executors.newSingleThreadScheduledExecutor(runnable ->
		{
			final Thread thread = new Thread(runnable, "profit-tracker-prices");
			thread.setDaemon(true);
			return thread;
		});
		executor.execute(this::refresh);
		executor.scheduleWithFixedDelay(this::refresh, config.priceRefreshSeconds(), config.priceRefreshSeconds(), TimeUnit.SECONDS);
	}

	void stop()
	{
		if (executor != null)
		{
			executor.shutdownNow();
		}
	}

	@Override
	public int getLivePrice(int itemId)
	{
		final int canonicalId = itemManager.canonicalize(itemId);
		final Integer wikiPrice = wikiPrices.get(canonicalId);
		if (wikiPrice != null && wikiPrice > 0)
		{
			return wikiPrice;
		}

		final int runelitePrice = itemManager.getItemPrice(canonicalId);
		if (runelitePrice > 0)
		{
			return runelitePrice;
		}

		return 0;
	}

	private void refresh()
	{
		try
		{
			final HttpURLConnection connection = (HttpURLConnection) new URL(LATEST_PRICES_URL).openConnection();
			connection.setRequestProperty("User-Agent", USER_AGENT);
			connection.setConnectTimeout(5000);
			connection.setReadTimeout(10000);

			try (InputStreamReader reader = new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))
			{
				final JsonObject root = new com.google.gson.JsonParser().parse(reader).getAsJsonObject();
				final JsonObject data = root.getAsJsonObject("data");
				final Map<Integer, Integer> refreshed = new ConcurrentHashMap<>();

				for (Map.Entry<String, JsonElement> entry : data.entrySet())
				{
					final int itemId = Integer.parseInt(entry.getKey());
					final JsonObject price = entry.getValue().getAsJsonObject();
					final int value = choosePrice(price);
					if (value > 0)
					{
						refreshed.put(itemId, value);
					}
				}

				wikiPrices.clear();
				wikiPrices.putAll(refreshed);
				lastRefresh = Instant.now();
				usingWikiPrices = true;
			}
		}
		catch (Exception ex)
		{
			usingWikiPrices = false;
			log.debug("Unable to refresh OSRS Wiki live prices", ex);
		}
	}

	static int choosePrice(JsonObject price)
	{
		final int high = getInt(price, "high");
		final int low = getInt(price, "low");
		if (high > 0 && low > 0)
		{
			return (high + low) / 2;
		}
		return Math.max(high, low);
	}

	private static int getInt(JsonObject object, String key)
	{
		final JsonElement element = object.get(key);
		return element == null || element.isJsonNull() ? 0 : element.getAsInt();
	}
}

package com.profittracker;

import java.time.Duration;
import java.time.Instant;
import java.util.Collection;
import java.util.Collections;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.Map;
import lombok.Getter;
import net.runelite.client.game.ItemStack;

class ProfitTrackerSession
{
	private final Map<String, ProfitTrackerTarget> targets = new LinkedHashMap<>();
	private final Deque<ProfitTrackerNotableDrop> notableDrops = new LinkedList<>();

	@Getter
	private Instant startedAt;

	@Getter
	private long lootValue;

	@Getter
	private long supplyCost;

	private Instant pausedAt;
	private Duration pausedDuration = Duration.ZERO;

	void recordKill(String npcName, Collection<ItemStack> drops, ProfitTrackerPriceLookup prices, long notableThreshold)
	{
		if (isPaused())
		{
			return;
		}

		if (startedAt == null)
		{
			startedAt = Instant.now();
		}

		final ProfitTrackerTarget target = targets.computeIfAbsent(npcName, ProfitTrackerTarget::new);
		final int killCount = target.getKills() + 1;
		long killValue = 0;
		for (ItemStack drop : drops)
		{
			if (drop.getId() <= 0 || drop.getQuantity() <= 0)
			{
				continue;
			}

			final long value = (long) prices.getLivePrice(drop.getId()) * drop.getQuantity();
			killValue += value;
			target.recordDrop(drop.getId(), drop.getQuantity(), value);
			if (notableThreshold > 0 && value >= notableThreshold)
			{
				notableDrops.addFirst(new ProfitTrackerNotableDrop(npcName, drop.getId(), drop.getQuantity(), value, killCount));
			}
		}

		lootValue += killValue;
		target.recordKill(killValue);
	}

	void recordKill(String npcName, Collection<ItemStack> drops, ProfitTrackerPriceLookup prices)
	{
		recordKill(npcName, drops, prices, Long.MAX_VALUE);
	}

	void recordSupplyCost(long value)
	{
		if (value <= 0 || isPaused())
		{
			return;
		}

		supplyCost += value;
	}

	void reset()
	{
		targets.clear();
		notableDrops.clear();
		startedAt = null;
		lootValue = 0;
		supplyCost = 0;
		pausedAt = null;
		pausedDuration = Duration.ZERO;
	}

	boolean isStarted()
	{
		return startedAt != null;
	}

	int getKillCount()
	{
		return targets.values().stream().mapToInt(ProfitTrackerTarget::getKills).sum();
	}

	long getProfit()
	{
		return lootValue - supplyCost;
	}

	Duration getElapsed()
	{
		if (startedAt == null)
		{
			return Duration.ZERO;
		}

		final Instant end = pausedAt == null ? Instant.now() : pausedAt;
		final Duration elapsed = Duration.between(startedAt, end).minus(pausedDuration);
		return elapsed.isNegative() ? Duration.ZERO : elapsed;
	}

	void setStartedAt(Instant startedAt)
	{
		this.startedAt = startedAt;
	}

	boolean isPaused()
	{
		return pausedAt != null;
	}

	void togglePaused()
	{
		if (!isStarted())
		{
			return;
		}

		if (pausedAt == null)
		{
			pausedAt = Instant.now();
			return;
		}

		pausedDuration = pausedDuration.plus(Duration.between(pausedAt, Instant.now()));
		pausedAt = null;
	}

	String getStatus()
	{
		if (!isStarted())
		{
			return "Waiting for loot";
		}
		return isPaused() ? "Paused" : "Tracking";
	}

	long getProfitPerHour()
	{
		final long seconds = Math.max(1, getElapsed().getSeconds());
		return getProfit() * 3600 / seconds;
	}

	Collection<ProfitTrackerTarget> getTargets()
	{
		return targets.values();
	}

	Collection<ProfitTrackerNotableDrop> getNotableDrops()
	{
		return Collections.unmodifiableCollection(notableDrops);
	}
}

package com.profittracker;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Getter;

class ProfitTrackerTarget
{
	@Getter
	private final String name;

	@Getter
	private int kills;

	@Getter
	private long lootValue;

	private final Map<Integer, ProfitTrackerDrop> drops = new LinkedHashMap<>();

	ProfitTrackerTarget(String name)
	{
		this.name = name;
	}

	void recordKill(long value)
	{
		kills++;
		lootValue += value;
	}

	void recordDrop(int itemId, int quantity, long value)
	{
		drops.computeIfAbsent(itemId, ProfitTrackerDrop::new).add(quantity, value);
	}

	long getAverageKillValue()
	{
		return kills == 0 ? 0 : lootValue / kills;
	}

	Map<Integer, ProfitTrackerDrop> getDrops()
	{
		return drops;
	}

	long getProfitShare(long totalProfit, long totalLoot)
	{
		if (totalLoot <= 0)
		{
			return 0;
		}
		return totalProfit * lootValue / totalLoot;
	}
}

